(function(global){
'use strict';
// Fail-closed, read-only adapter. The manifest is generated by LotScope from the
// same authoritative polygons, never recomputed from decorative Pondy geometry.
const M=(typeof module!=='undefined'&&module.exports)?require('./lot2-design-4-roof-intervals.js'):global.Lot2Design4RoofIntervals;
const R=(typeof module!=='undefined'&&module.exports)?require('./lot2-design-4-roof-sot.js'):global.Lot2Design4RoofSOT;
const D=(typeof module!=='undefined'&&module.exports)?require('./lot2-design-4.js'):global.Lot2Design4;
const VERSION='lotscope-verified-roof-intervals-v1';
const VIEW_IDS=Object.freeze(['north','south','east','west','pondy-iso-01']);
function reject(reason){return {status:'WITHHELD',segments:[],counts:null,reason};}
function currentOwnerPolygon(ownerId){
 if(!D)return null;
 if(ownerId.startsWith('home-')){
  const h=(D.HOMES||[]).find(x=>'home-'+String(x.unit).toLowerCase()===ownerId);
  return h?(h.poly||[[h.x,h.y],[h.x+h.w,h.y],[h.x+h.w,h.y+h.d],[h.x,h.y+h.d]]):null;
 }
 const g=(D.GARAGES||[]).find(x=>'garage-'+String(x.unit).toLowerCase()===ownerId);
 return g?[[g.x,g.y],[g.x+g.w,g.y],[g.x+g.w,g.y+g.d],[g.x,g.y+g.d]]:null;
}
function ownerMatchesLiveGeometry(roof){
 try{
  const key=JSON.parse(roof.ownerGeometryKey);
  const live=currentOwnerPolygon(roof.ownerId);
  return key&&key.id===roof.ownerId&&key.rotationDeg===0&&Array.isArray(live)
    &&JSON.stringify(key.polygon)===JSON.stringify(live);
 }catch{return false;}
}
function resolve(roof,viewId){
 if(!R||!D||!M||!M.manifest)return reject('Interval model unavailable');
 const manifest=M.manifest;
 if(manifest.schemaVersion!==VERSION||manifest.renderScope!=='CONCEPT_ONLY_NOT_FOR_CONSTRUCTION'||
    manifest.sourceRoofSchema!==R.SCHEMA_VERSION||manifest.sourceSnapshot!=='pondy-d4'||
    manifest.owners?.length!==4||
    JSON.stringify(manifest.camera?.cardinalDepthDirections)!==JSON.stringify({north:'NEGATIVE_Y',south:'POSITIVE_Y',east:'POSITIVE_X',west:'NEGATIVE_X'})||
    JSON.stringify(manifest.camera?.screenX)!==JSON.stringify([5.2,-3.2,0])||
    JSON.stringify(manifest.camera?.screenY)!==JSON.stringify([-1.55,-1.35,-8.2])||
    JSON.stringify(manifest.camera?.depth)!==JSON.stringify([-26.24,-42.64,11.98])||
    JSON.stringify(manifest.camera?.screenTranslation)!==JSON.stringify([299.2,688.6]))return reject('Imported roof interval contract or source mismatch');
 if(!roof||!R.roofIsAuthoritative(roof)||!ownerMatchesLiveGeometry(roof))return reject('Roof lock or current owner geometry missing');
 if(!VIEW_IDS.includes(viewId))return reject('Unknown camera / elevation view');
 const imported=manifest.owners.find(x=>x.ownerId===roof.ownerId);
 if(!imported||imported.roofId!==roof.id||!M.matchingOwner(roof,imported))return reject('Imported locked surface does not match current roof');
 const entry=imported.views?.[viewId];
 if(!entry||!['INTERVAL_VERIFIED','REVIEW_REQUIRED'].includes(entry.status)||!entry.counts||
   !Array.isArray(entry.segments)||entry.segments.length<1)return reject('Visibility interval data missing');
 if(entry.counts.unresolved>0||entry.counts.edgeOnFaces>0||entry.counts.collapsedEdges>0){
  if(entry.status!=='REVIEW_REQUIRED')return reject('A review-needed view was marked verified');
 }
 if(entry.segments.some(s=>!s||!['VISIBLE','HIDDEN','UNRESOLVED'].includes(s.visibility)||
    !Array.isArray(s.start)||!Array.isArray(s.end)||s.start.length!==2||s.end.length!==2||
    [...s.start,...s.end].some(n=>typeof n!=='number'||!Number.isFinite(n))))return reject('Malformed imported edge');
 if(entry.status==='INTERVAL_VERIFIED'&&entry.segments.some(s=>s.visibility==='UNRESOLVED'))return reject('Visibility claimed for unresolved intervals');
 return entry;
}
const api={VERSION,resolve,currentOwnerPolygon,ownerMatchesLiveGeometry};
if(typeof module!=='undefined'&&module.exports)module.exports=api;
global.Lot2Design4RoofIntervalAdapter=api;
})(typeof window!=='undefined'?window:globalThis);
